# 단방향 데이터 흐름 예시: Python 3에서 실행 가능한 코드
state = {"count": 1}
props = {"count": state["count"]}
print(props["count"])

# Virtual DOM 예시: Python 3에서 실행 가능한 코드
old = {"text": "A"}
new = {"text": "B"}
print(old != new)

# 커스텀 훅 예시: Python 3에서 실행 가능한 코드
def use_toggle(initial=False):
    value = initial
    return value, (lambda: not value)
value, toggle = use_toggle()
print(value, toggle())

# Redux Toolkit 예시: Python 3에서 실행 가능한 코드
slice_state = {"value": 0}
def increment(s):
    return {"value": s["value"] + 1}
print(increment(slice_state))

# 불변성(Immutability) 예시: Python 3에서 실행 가능한 코드
old = {"count": 1}
new = {**old, "count": old["count"] + 1}
print(old, new)

# 메모이제이션(useMemo/useCallback) 예시: Python 3에서 실행 가능한 코드
cache = {}
def square(x):
    cache[x] = cache.get(x, x*x)
    return cache[x]
print(square(4), square(4))

# React.memo 예시: Python 3에서 실행 가능한 코드
prev_props = {"name": "Kim"}
next_props = {"name": "Kim"}
print(prev_props == next_props)

# 에러 바운더리 예시: Python 3에서 실행 가능한 코드
try:
    raise ValueError("render failed")
except ValueError:
    print("fallback UI")

# 소스맵 예시: Python 3에서 실행 가능한 코드
sourcemap = {"bundle.js:1": "src/app.js:10"}
print(sourcemap["bundle.js:1"])

# CSS-in-JS 예시: Python 3에서 실행 가능한 코드
props = {"primary": True}
style = {"color": "blue" if props["primary"] else "gray"}
print(style)

# 디자인 시스템 예시: Python 3에서 실행 가능한 코드
tokens = {"color.primary": "#0055ff", "radius.sm": 4}
print(tokens["color.primary"])

# 접근성(A11y) 예시: Python 3에서 실행 가능한 코드
button = {"role": "button", "label": "저장"}
print(bool(button["label"]))

# ARIA 역할 예시: Python 3에서 실행 가능한 코드
element = {"role": "dialog", "aria-modal": True}
print(element["role"])

# 다국어 날짜/숫자 포맷 예시: Python 3에서 실행 가능한 코드
date = {"year": 2026, "month": 5, "day": 7}
print(f"{date["year"]}-{date["month"]:02d}-{date["day"]:02d}")

# 웹 성능 지표(CWV) 예시: Python 3에서 실행 가능한 코드
cwv = {"LCP": 2.0, "INP": 150, "CLS": 0.05}
print(cwv)

# 성능 프로파일링 예시: Python 3에서 실행 가능한 코드
times = {"render": 12, "fetch": 80, "parse": 20}
print(max(times, key=times.get))

# Lighthouse 예시: Python 3에서 실행 가능한 코드
scores = {"performance": 92, "accessibility": 88}
print(min(scores.values()))

# 마이크로 프론트엔드 예시: Python 3에서 실행 가능한 코드
apps = {"checkout": "team-a", "profile": "team-b"}
print(apps.keys())

# 모듈 페더레이션(Module Federation) 예시: Python 3에서 실행 가능한 코드
remote = {"Button": "remote/Button"}
print(remote["Button"])

# 웹 컴포넌트(Web Components) 예시: Python 3에서 실행 가능한 코드
component = {"tag": "user-card", "shadow": True}
print(component["tag"])

# Shadow DOM 예시: Python 3에서 실행 가능한 코드
shadow_styles = {"button": "local"}
global_styles = {"button": "global"}
print(shadow_styles["button"])
